        String chart=tab==1&&repo.charts.current!=null?repo.charts.current.sourceId+":"+repo.charts.current.raw.optString("id"):"";
        String library=tab==2?libraryUi.pageKey():"";if(!renderedQuery.equals(repo.query)||!renderedChart.equals(chart)||!renderedLibrary.equals(library)){renderedQuery=repo.query;renderedChart=chart;renderedLibrary=library;position=0;offset=0;anchor=null;}
