    private void searchHistory(){
        List<String> history=new ArrayList<>(repo.library.history);if(history.isEmpty())editingHistory=false;
        LinearLayout head=row();weighted(head,text("最近搜索",17,ink,true));
        if(!history.isEmpty()){
            if(editingHistory)head.addView(historyAction("清空",()->new UiSheet.Builder(this).setTitle("清空搜索历史？").setMessage("清空后无法恢复。").setPositiveButton("清空",(d,w)->{repo.editLibrary(l->l.history.clear(),(ok,error)->{if(ok){editingHistory=false;renderContent();}});}).setNegativeButton("取消",null).show()));
            head.addView(historyAction(editingHistory?"完成":"管理",()->{editingHistory=!editingHistory;renderContent();}));
        }else head.setMinimumHeight(dp(48));
        content.addView(head);
        if(history.isEmpty()){space(content,8);content.addView(text("搜一首喜欢的歌，最近搜索会留在这里",13,muted,false));return;}
        HistoryTags tags=new HistoryTags();
        for(String query:history){
            LinearLayout chip=row();chip.setGravity(Gravity.CENTER_VERTICAL);chip.setMinimumWidth(dp(48));chip.setMinimumHeight(dp(48));
            android.graphics.drawable.RippleDrawable fill=new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x18245e4f),shape(0xffecefe9,18),null);
            chip.setBackground(new android.graphics.drawable.InsetDrawable(fill,0,dp(6),0,dp(6)));chip.setPadding(dp(14),dp(6),dp(editingHistory?10:14),dp(6));
            TextView label=text(query,14,ink,false);label.setSingleLine(true);label.setEllipsize(android.text.TextUtils.TruncateAt.END);chip.addView(label,new LinearLayout.LayoutParams(-2,-2,1));
            if(editingHistory){TextView remove=text("×",18,muted,false);remove.setPadding(dp(8),0,0,0);remove.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);chip.addView(remove);}
            label.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);chip.setFocusable(true);chip.setContentDescription((editingHistory?"删除搜索记录：":"搜索：")+query);
            chip.setOnClickListener(v->{if(editingHistory){repo.editLibrary(l->l.history.remove(query));}else{searchInput.setText(query);search();}});
            chip.setOnLongClickListener(v->{if(editingHistory)return false;editingHistory=true;renderContent();return true;});tags.addView(chip);
        }
        content.addView(tags,new LinearLayout.LayoutParams(-1,-2));
    }
    /** Wrap compact history tags using the actual available width, including after rotation. */
    private final class HistoryTags extends ViewGroup {
        HistoryTags(){super(MainActivity.this);}
        @Override protected void onMeasure(int widthSpec,int heightSpec){
            int width=MeasureSpec.getSize(widthSpec),limit=Math.max(0,width-getPaddingLeft()-getPaddingRight()),x=0,y=0,rowHeight=0;
            for(int i=0;i<getChildCount();i++){View child=getChildAt(i);child.measure(MeasureSpec.makeMeasureSpec(limit,MeasureSpec.AT_MOST),MeasureSpec.makeMeasureSpec(0,MeasureSpec.UNSPECIFIED));int w=child.getMeasuredWidth(),h=child.getMeasuredHeight();if(x>0&&x+w>limit){y+=rowHeight;x=0;rowHeight=0;}x+=w+dp(8);rowHeight=Math.max(rowHeight,h);}
            setMeasuredDimension(resolveSize(width,widthSpec),resolveSize(getPaddingTop()+y+rowHeight+getPaddingBottom(),heightSpec));
        }
        @Override protected void onLayout(boolean changed,int left,int top,int right,int bottom){
            int limit=right-left-getPaddingLeft()-getPaddingRight(),x=0,y=getPaddingTop(),rowHeight=0;boolean rtl=getLayoutDirection()==View.LAYOUT_DIRECTION_RTL;
            for(int i=0;i<getChildCount();i++){View child=getChildAt(i);int w=child.getMeasuredWidth(),h=child.getMeasuredHeight();if(x>0&&x+w>limit){y+=rowHeight;x=0;rowHeight=0;}int start=getPaddingLeft()+(rtl?limit-x-w:x);child.layout(start,y,start+w,y+h);x+=w+dp(8);rowHeight=Math.max(rowHeight,h);}
        }
        @Override protected ViewGroup.LayoutParams generateDefaultLayoutParams(){return new ViewGroup.LayoutParams(-2,-2);}
    }
