        Charts.Board board=charts.current;LinearLayout hero=column();hero.setPadding(dp(16),dp(12),dp(16),dp(12));hero.setBackground(shape(green,20));
        TextView eyebrow=text((repo.isAutomaticChart()?"自动选榜":"正在浏览")+(board.group.isEmpty()?"":"  /  "+SongText.clean(board.group)),11,Color.rgb(195,220,206),false);hero.addView(eyebrow);space(hero,6);
