    private void importDialog(){EditText input=new EditText(this);input.setHint("https://…/plugins.json");input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);LinearLayout wrap=column();wrap.setPadding(dp(24),dp(10),dp(24),0);UiSheet.styleInput(input);wrap.addView(input);TextView hint=text("支持订阅清单或单个 JS。插件会请求网络，请使用你信任的来源。",12,muted,false);space(wrap,12);wrap.addView(hint);new UiSheet.Builder(this).setTitle("添加音乐订阅").setView(wrap).setPositiveButton("导入",(d,w)->{tab=3;build();repo.importUrl(input.getText().toString());}).setNegativeButton("取消",null).show();}
    private void configDialog(Source s){LinearLayout form=column();form.setPadding(dp(20),dp(12),dp(20),dp(12));Map<String,EditText> inputs=new LinkedHashMap<>();for(int i=0;i<s.fields.length();i++){JSONObject field=s.fields.optJSONObject(i);if(field==null)continue;String key=field.optString("key");if(key.isEmpty())continue;form.addView(text(field.optString("name",key),14,ink,true));EditText input=new EditText(this);input.setSingleLine(true);input.setText(s.variables.optString(key,field.optString("defaultValue","")));input.setHint(field.optString("hint"));if(field.optString("type").equals("password"))input.setInputType(129);UiSheet.styleInput(input);form.addView(input);space(form,12);inputs.put(key,input);}
        if(inputs.isEmpty())form.addView(text("此插件没有声明可配置项。",14,muted,false));ScrollView view=new ScrollView(this);view.addView(form);new UiSheet.Builder(this).setTitle(s.name+" · 配置").setView(view).setPositiveButton("保存",(d,w)->{try{for(Map.Entry<String,EditText> e:inputs.entrySet())s.variables.put(e.getKey(),e.getValue().getText().toString());s.healthVersion++;s.failures=0;s.playbackHealth.restore();s.message="配置已保存，请复检";repo.save();}catch(Exception e){toast(e.getMessage());}}).setNegativeButton("取消",null).show();}
    private void play(Song song,List<Song> queue,Route route){if(PlaybackService.instance==null){toast("播放器正在准备，请稍后重试");return;}if(route==null)PlaybackUi.play(this,repo,song,visibleResults(queue));else PlaybackService.instance.play(song,visibleResults(queue),route);}
    private void updateRowState(View row){Song song=(Song)row.getTag();PlaybackService p=PlaybackService.instance;boolean active=p!=null&&p.current!=null&&p.current.key.equals(song.key);if(row.isActivated()!=active||row instanceof MainSongRow){row.setActivated(active);if(row instanceof MainSongRow)row.setBackgroundColor(active?0xffe4eee5:Color.TRANSPARENT);}TextView count=row.findViewWithTag("sourceCount");if(count!=null){String value=(repo.playableCount(song)>0?"• ":"")+song.routes.size()+" 源 ›";if(!value.contentEquals(count.getText()))count.setText(value);}}
    private void updateRowStates(){if(scroll!=null)for(View row:scroll.songRows())updateRowState(row);}
    private void updateMiniProgress(){if(miniTitle==null)return;PlaybackService s=PlaybackService.instance;if(s==null||s.current==null)return;long total=s.player.getDuration();miniProgress.setProgress(total>0?(int)(s.displayPosition()*1000/total):0);String lyric=s.currentLyric();String status=s.isRecovering()||s.needsRetry()||lyric.isEmpty()?s.status:lyric;if(!status.contentEquals(miniStatus.getText()))miniStatus.setText(status);}
    private void updateMini(){if(miniTitle==null)return;PlaybackService s=PlaybackService.instance;if(s==null||s.current==null){miniTitle.setText("选择一首歌，开始听");miniStatus.setText("搜索 · 收藏 · 我的歌单");miniButton.setImageResource(R.drawable.player_play);miniButton.setContentDescription("播放");miniProgress.setProgress(0);miniCover.bind(null);return;}miniCover.bind(s.current);long total=s.player.getDuration();miniProgress.setProgress(total>0?(int)(s.displayPosition()*1000/total):0);miniTitle.setText(s.current.title+" · "+s.current.artist);String lyric=s.currentLyric();miniStatus.setText(s.isRecovering()||s.needsRetry()||lyric.isEmpty()?s.status:lyric);miniButton.setImageResource(s.needsRetry()?R.drawable.player_retry:s.wantsPlayback()?R.drawable.player_pause:R.drawable.player_play);miniButton.setContentDescription(s.needsRetry()?"重试播放":s.wantsPlayback()?"暂停":"播放");}
    private void openHelp(){startActivity(new Intent(this,HelpActivity.class));}
    private void openPlayer(){startActivity(new Intent(this,PlayerActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP));}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
